"""
    Return the attibutes in an object in a list.
        :param object: object
    """
def attr_in_object(object: Any) -> object {
    members = [
        attr
        for attr in dir(object)
        if (not callable(getattr(object, attr)) and not attr.startswith("__"))
    ];
    return members;
}

